  const result = spawnSync(process.execPath, [path.resolve(contract.script), ...contract.args.map(a => a === '$NODE' ? process.execPath : a)], { encoding: 'utf8', timeout: contract.timeoutMs, env: { PATH: process.env.PATH || '' } });
